void lref_set::clear()
{
  if (node_count != 0)
  {
    erase_label(this, header->parent);
    header->left = header;
    header->parent = 0;
    header->right = header;
    node_count = 0;
  }
}

void pref_set::clear()
{
  if (node_count != 0)
  {
    erase_ptr(this, header->parent);
    header->left = header;
    header->parent = 0;
    header->right = header;
    node_count = 0;
  }
}

